<?php
declare(strict_types=1);
namespace DigiForgePrintifyConnector\Preparation;
use DigiForge\Connector\Printify\ShopBinding;
/** Price-only core observations. Self-hashes detect drift and never confer authority. */
final class ExistingProductSourceReadModel {
 public static function observe(ShopBinding $s,int $actor,array $r):array|\WP_Error {
  try{
   if(!NativePortSchema::valid('json_object',$r)||strlen(json_encode($r,JSON_THROW_ON_ERROR))>65536)throw new \InvalidArgumentException();
   $keys=['schema','version','scope_fingerprint','actor_id','shop_key','integration_id','credential_reference','provider_shop_id','environment','product_id','product_version_id','provider_mapping_id','asset_spec_id','operation','plan_hash','package_hash','artwork_version_hash','supplier_evidence_hash','provider_product_id','blueprint_id','provider_id','variant_id','price_minor','currency','payload_fingerprint','product_read_receipt_hash','source_read_policy_revision','source_read_producer_audit_id','source_read_producer_actor_id','adopted_product_receipt_hash','adoption_producer_audit_id','adoption_producer_actor_id','observed_at','adopted_at','plan_policy_hash','plan_policy_revision','native_product_version','provider_currentness_verified','provider_version_cas_verified','revalidation_before_mutation_required','business_package_binding_approved','source_approval_cas_verified','mutation_authorized','dispatch_permitted','independent_checkpoint_verified','supplier_certified','external_execution_authorized','release_hold','evidence_hash'];
   if($s->shopId!==2||$s->shopKey!=='personalized_pod'||$actor<1||$s->expiresAt<=time()||array_diff(array_keys($r),$keys)||array_diff($keys,array_keys($r)))throw new \InvalidArgumentException();
   foreach(['schema'=>'DF_NATIVE_EXISTING_PRODUCT_MUTATION_EVIDENCE_1','version'=>'1.0.0','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'shop_key'=>$s->shopKey,'integration_id'=>$s->integrationId,'credential_reference'=>$s->credential->integrationId,'provider_shop_id'=>$s->providerShopId,'environment'=>$s->environment,'operation'=>'PRODUCT_UPDATE','currency'=>null,'native_product_version'=>null,'provider_currentness_verified'=>false,'provider_version_cas_verified'=>false,'revalidation_before_mutation_required'=>true,'business_package_binding_approved'=>false,'source_approval_cas_verified'=>false,'mutation_authorized'=>false,'dispatch_permitted'=>false,'independent_checkpoint_verified'=>false,'supplier_certified'=>false,'external_execution_authorized'=>false,'release_hold'=>true]as $key=>$value)if($r[$key]!==$value)throw new \InvalidArgumentException();
   foreach(['product_id','product_version_id','provider_mapping_id','asset_spec_id','blueprint_id','provider_id','variant_id','price_minor','source_read_policy_revision','source_read_producer_audit_id','source_read_producer_actor_id','adoption_producer_audit_id','adoption_producer_actor_id','plan_policy_revision']as $key)if(!is_int($r[$key])||$r[$key]<1)throw new \InvalidArgumentException();
   if($r['adoption_producer_audit_id']<=$r['source_read_producer_audit_id']||!is_string($r['provider_product_id'])||!preg_match('/^[A-Za-z0-9_-]{1,128}$/D',$r['provider_product_id']))throw new \InvalidArgumentException();
   foreach(['plan_hash','package_hash','artwork_version_hash','supplier_evidence_hash','payload_fingerprint','product_read_receipt_hash','adopted_product_receipt_hash','plan_policy_hash','evidence_hash']as $key)if(!is_string($r[$key])||!preg_match('/^[a-f0-9]{64}$/D',$r[$key]))throw new \InvalidArgumentException();
   foreach(['observed_at','adopted_at']as $key){if(!is_string($r[$key]))throw new \InvalidArgumentException();$date=\DateTimeImmutable::createFromFormat('!Y-m-d\TH:i:sP',$r[$key]);if($date===false||$date->format('c')!==$r[$key]||$date->getTimestamp()>time())throw new \InvalidArgumentException();}
   $hash=$r['evidence_hash'];unset($r['evidence_hash']);if(!hash_equals(MutationIntent::hash($r),$hash))throw new \InvalidArgumentException();
   return ['schema'=>'DF_COMPANION_EXISTING_PRODUCT_SOURCE_VIEW_1','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'state'=>'PRICE_ONLY_SOURCE_OBSERVED_MUTATION_BLOCKED','operation'=>'PRODUCT_UPDATE','payload_scope'=>'PRICE_ONLY','business_product_id'=>$r['product_id'],'business_product_version_id'=>$r['product_version_id'],'provider_product_id'=>$r['provider_product_id'],'blueprint_id'=>$r['blueprint_id'],'provider_id'=>$r['provider_id'],'variant_id'=>$r['variant_id'],'price_minor'=>$r['price_minor'],'currency'=>null,'observed_at'=>$r['observed_at'],'adopted_at'=>$r['adopted_at'],'source_evidence_hash'=>$hash,'native_product_version'=>null,'provider_currentness_verified'=>false,'provider_version_cas_verified'=>false,'full_product_draft_equivalence_verified'=>false,'native_version_counters_verified'=>false,'independent_checkpoint_verified'=>false,'source_approval_cas_verified'=>false,'supplier_certified'=>false,'mutation_authorized'=>false,'dispatch_permitted'=>false,'source_authenticated'=>false,'trusted_receipt'=>false,'current_core_verification_required'=>true,'revalidation_before_mutation_required'=>true,'manual_review_required'=>true,'read_only'=>true,'retry_permitted'=>false,'network_request_permitted'=>false,'external_execution_authorized'=>false];
  }catch(\Throwable){return new \WP_Error('printify_existing_product_source_denied','Exact current price-only core source required; no mutation authorized.',['manual_review_required'=>true,'read_only'=>true,'retry_permitted'=>false,'external_execution_authorized'=>false]);}
 }
}
